"""Server-rendered templates for Astra's persistent evidence views."""

from __future__ import annotations

THEME = r"""
:root{color-scheme:light;--ink:#13233f;--muted:#60708a;--paper:#f4f1e9;--surface:#fffdf8;--line:#dbe0e7;--navy:#17365f;--blue:#3569a8;--teal:#13877f;--mint:#dff3ed;--coral:#e86f51;--amber:#b67816;--red:#a53945;--shadow:0 18px 45px rgba(24,48,80,.10);--radius:20px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 10% 0,#e9f4f0 0,transparent 34rem),var(--paper);color:var(--ink);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{width:min(1180px,calc(100% - 2rem));margin:auto}.skip{position:absolute;left:-999px}.skip:focus{left:1rem;top:1rem;z-index:20;background:#fff;padding:.7rem}.topbar{position:sticky;top:0;z-index:10;background:rgba(19,35,63,.96);backdrop-filter:blur(14px);color:#fff;border-bottom:3px solid var(--teal)}.topbar .shell{min-height:74px;display:flex;align-items:center;justify-content:space-between;gap:1.5rem}.brand{color:#fff;text-decoration:none;font-weight:900;font-size:1.12rem;letter-spacing:.01em}.brand small{display:block;color:#9edbd3;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase}.nav{display:flex;gap:.35rem;align-items:center;flex-wrap:wrap}.nav a{color:#dce9f7;text-decoration:none;font-weight:750;padding:.48rem .7rem;border-radius:999px}.nav a:hover,.nav a[aria-current=page]{background:#284a75;color:#fff}.crumbs{display:flex;gap:.5rem;align-items:center;color:var(--muted);font-size:.86rem;margin:1.4rem 0}.crumbs a{color:var(--blue);text-decoration:none}.hero{padding:1rem 0 1.5rem;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.7fr);gap:1.3rem;align-items:end}.eyebrow{margin:0;color:var(--teal);font-weight:900;font-size:.72rem;letter-spacing:.12em;text-transform:uppercase}.hero h1{font-size:clamp(2.3rem,6vw,4.8rem);line-height:.98;letter-spacing:-.045em;margin:.35rem 0 .8rem;max-width:14ch}.lede{font-size:1.08rem;color:var(--muted);max-width:68ch}.live-card,.card,.metric,.outcome,.notice{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.live-card{padding:1.1rem}.live-row{display:flex;gap:.6rem;align-items:center;font-weight:850}.live-dot{width:.72rem;height:.72rem;border-radius:50%;background:var(--teal);box-shadow:0 0 0 .38rem rgba(19,135,127,.14);animation:pulse 2s ease-out infinite}.live-dot.offline{background:var(--red);box-shadow:none;animation:none}@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(19,135,127,.3)}70%{box-shadow:0 0 0 .55rem rgba(19,135,127,0)}100%{box-shadow:0 0 0 0 rgba(19,135,127,0)}}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem;margin:1rem 0 1.4rem}.metric{padding:1rem}.metric strong{display:block;font-size:1.8rem}.metric span{color:var(--muted);font-size:.85rem}.section{margin:1.6rem 0 2.4rem}.section-head{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin-bottom:.8rem}.section h2{font-size:1.45rem;margin:0}.section-head p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:.9rem}.card{padding:1.1rem;transition:transform .18s ease,box-shadow .18s ease}.card:hover{transform:translateY(-3px);box-shadow:0 22px 50px rgba(24,48,80,.14)}.card h3{margin:.2rem 0 .5rem}.card-link{color:inherit;text-decoration:none}.meta{color:var(--muted);font-size:.87rem}.pill{display:inline-flex;align-items:center;border-radius:999px;padding:.2rem .58rem;font-size:.7rem;font-weight:900;letter-spacing:.04em;text-transform:uppercase;background:#e9eff7;color:var(--navy)}.pill.review{background:#fff0d2;color:#744b00}.pill.ok{background:var(--mint);color:#075e58}.pill.sim{background:#ffe7df;color:#8a3c27}.actions{display:flex;flex-wrap:wrap;gap:.65rem;margin-top:1rem}.button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;background:var(--navy);color:#fff;text-decoration:none;border:0;border-radius:12px;padding:.72rem 1rem;font:inherit;font-weight:850;cursor:pointer}.button.secondary{background:transparent;color:var(--navy);border:1px solid #9fb1c8}.button.teal{background:var(--teal)}.outcome{padding:1.25rem;border-left:8px solid var(--teal)}.outcome.review{border-left-color:var(--amber)}.outcome h2{margin:.25rem 0}.role{background:#f5f8fb;border:1px solid var(--line);padding:.8rem;border-radius:12px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.compare article{background:#f5f7fa;border-radius:14px;padding:1rem;border-top:4px solid var(--navy)}.compare article:last-child{border-color:var(--teal)}.timeline{list-style:none;padding:0}.timeline li{border-left:3px solid var(--line);padding:0 0 1rem 1rem;margin-left:.4rem}.pipeline{display:grid;grid-template-columns:repeat(6,1fr);gap:.5rem}.pipeline-step{background:#fff;border:1px solid var(--line);border-radius:12px;padding:.7rem;font-size:.76rem}.pipeline-step.complete{background:var(--mint);border-color:#8bc9be}.pipeline-step.current{border-color:var(--blue);box-shadow:0 0 0 2px #dce9f8}.pipeline-step.blocked{background:#fff0f1;border-color:#e8a1aa}.watch-list{list-style:none;padding:0;margin:0}.watch-incident{border-top:1px solid var(--line);padding:.8rem 0}.watch-incident a{font-weight:850;color:var(--navy)}.mismatch{background:#fff0f1;border:2px solid var(--red);border-radius:16px;padding:1rem}.mismatch h2{color:var(--red);margin:0}.notice{padding:1rem;border-left:6px solid var(--amber)}code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f3f7;border:1px solid var(--line);border-radius:12px;padding:.85rem;font-size:.8rem}label{display:block;font-weight:750;margin:.7rem 0}select,textarea,input{display:block;width:100%;margin-top:.3rem;border:1px solid #91a0b5;border-radius:10px;padding:.65rem;background:#fff;font:inherit}textarea{min-height:5rem}.footer{border-top:1px solid var(--line);margin-top:3rem;padding:1.6rem 0;color:var(--muted)}.footer-grid{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}@media(max-width:800px){.hero{grid-template-columns:1fr}.metrics{grid-template-columns:1fr}.pipeline{grid-template-columns:repeat(2,1fr)}.compare{grid-template-columns:1fr}.topbar .shell{align-items:flex-start;flex-direction:column;padding:.8rem 0}.nav{width:100%;overflow:auto;flex-wrap:nowrap}.hero h1{font-size:3rem}}@media(max-width:520px){.shell{width:min(100% - 1rem,1180px)}.pipeline{grid-template-columns:1fr}.section-head{align-items:flex-start;flex-direction:column}}
"""

# The compact navigation deliberately wraps rather than hiding the project guide
# behind a horizontal scroll affordance on narrow screens.
THEME += r"""
@media(max-width:800px){.nav{width:100%;overflow:visible;flex-wrap:wrap}.nav a{padding:.4rem .58rem;font-size:.9rem}}
code{overflow-wrap:anywhere;word-break:break-word}
"""

BASE = (
    r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{% block title %}Astra{% endblock %}</title><style>"""
    + THEME
    + r"""</style>{% block head %}{% endblock %}</head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="shell"><a class="brand" href="/"><small>Braille Errata Relay</small>Astra</a><nav class="nav" aria-label="Primary"><a href="/" {% if nav == 'overview' %}aria-current="page"{% endif %}>Overview</a><a href="/watch" {% if nav == 'watch' %}aria-current="page"{% endif %}>Live watch</a><a href="/#baselines">Baselines</a><a href="/#reports">Reports</a><a href="/test-astra" {% if nav == 'test' %}aria-current="page"{% endif %}>Test Astra</a></nav></div></header><main id="main" class="shell">{% block content %}{% endblock %}</main><footer class="footer"><div class="shell footer-grid"><span>Astra is a report-first production overlay.</span><span>Physical endpoint simulated · production authority remains human.</span></div></footer></body></html>"""
)

INDEX = r"""{% extends 'base.html' %}{% block title %}Astra · Evidence dashboard{% endblock %}{% block content %}<div class="crumbs"><span>Home</span><span>›</span><strong>Evidence dashboard</strong></div><section class="hero"><div><p class="eyebrow">Source-to-Braille integrity</p><h1>Catch the correction before the next copy.</h1><p class="lede">Astra watches an authoritative source, rebuilds deterministic Braille evidence, explains semantic impact with Gemini, and stops at accountable human gates.</p><div class="actions"><a class="button teal" href="/watch">Open live watch</a><a class="button secondary" href="/test-astra">Explore Astra</a></div></div><aside class="live-card"><div class="live-row"><span class="live-dot"></span>Live evidence service</div><p class="meta">Server-rendered from durable Cloud records. This browser has no Drive, CUPS, or device credentials.</p>{% if hosted_read_only %}<span class="pill ok">Public read-only view · GET only</span>{% else %}<span class="pill">Private operator view</span>{% endif %}</aside></section>{% if error %}<p class="notice">{{ error }}</p>{% endif %}<section class="metrics"><article class="metric"><strong>{{ summary.baselines|default(baselines|length) }}</strong><span>registered baselines</span></article><article class="metric"><strong>{{ summary.total|default(incidents|length) }}</strong><span>persistent reports</span></article><article class="metric"><strong>{{ summary.blocked|default(0) }}</strong><span>human-review outcomes</span></article></section><section id="baselines" class="section"><div class="section-head"><div><p class="eyebrow">Persistent item 01</p><h2>Registered baselines</h2></div>{% if not hosted_read_only %}<a class="button secondary" href="/setup/source">Register baseline</a>{% endif %}</div><div class="grid">{% for baseline in baselines %}<a class="card card-link" href="/baselines/{{ baseline.baseline_id }}"><span class="pill ok">{{ baseline.status|replace('_',' ') }}</span><h3>{{ baseline.production_id }}</h3><p class="meta">{{ baseline.site_id }} · {{ baseline.queue_name }}</p><p><strong>BRF</strong> <code>{{ baseline.approved_brf_sha256[:14] }}…</code></p><p class="meta">Registered {{ baseline.created_at }}</p></a>{% else %}<article class="card"><h3>No baseline record available</h3><p class="meta">Registering a source creates immutable BRF lineage before monitoring begins.</p></article>{% endfor %}</div></section><section id="reports" class="section"><div class="section-head"><div><p class="eyebrow">Persistent item 02</p><h2>Past reports and human outcomes</h2></div><p>Newest durable evidence first</p></div><div class="grid">{% for incident in incidents %}<a class="card card-link" href="/incidents/{{ incident.incident_id }}"><span class="pill {% if incident.blocking_reason %}review{% else %}ok{% endif %}">{{ incident.review_state.state|replace('_',' ') }}</span><h3>Report {{ incident.incident_id[:12] }}…</h3><p>{{ incident.source_change_summary|default('Open the report for the authoritative source correction.') }}</p><p class="meta">{{ incident.page_impact_summary|default('Deterministic page impact is attached.') }}</p><p><strong>Next:</strong> {{ incident.next_safe_action|default('Review attributable evidence.') }}</p></a>{% else %}<article class="card"><h3>No reports yet</h3><p class="meta">The watch floor will surface the next durable correction.</p></article>{% endfor %}</div></section><section class="section"><div class="card"><p class="eyebrow">Two ways to explore</p><h2>Explore here, or reproduce the full floor.</h2><p>The hosted path is read-only and shows live durable evidence. The repository path provisions an isolated Google Cloud project, Drive source, Liblouis profile, and CUPS simulator.</p><div class="actions"><a class="button" href="/test-astra">Explore access paths</a>{% if source_document_url %}<a class="button secondary" href="{{ source_document_url }}" target="_blank" rel="noopener">View source document</a>{% endif %}</div></div></section>{% endblock %}"""

WATCH = r"""{% extends 'base.html' %}{% block title %}Astra · Live watch{% endblock %}{% block head %}<script src="/assets/watch.js" defer></script>{% endblock %}{% block content %}<div class="crumbs"><a href="/">Home</a><span>›</span><strong>Live watch</strong></div>{% if fixture_mode %}<p class="notice"><strong>SANITIZED DEMO FIXTURE</strong> · No cloud, Drive, CUPS, or human-record action is performed.</p>{% endif %}<section class="hero"><div><p class="eyebrow">Persistent item 03 · event stream</p><h1>Watching the authoritative source.</h1><p class="lede">Durable Drive reconciliation and incident evidence update here. Historical records never trigger a false alarm when the page first opens.</p></div><aside class="live-card"><div class="live-row"><span class="live-dot"></span><strong id="watch-connection" data-state="connected">{% if fixture_mode %}Connected{% elif hosted_read_only %}Hosted live view{% else %}Connecting{% endif %}</strong></div><p id="watch-automatic-cycle" class="meta">{{ watch.automatic_cycle }}</p></aside></section>{% if error %}<p class="notice">{{ error }}</p>{% endif %}<section id="mismatch-alert" class="mismatch" {% if not fixture_alert %}hidden{% endif %}><h2>SOURCE / PRODUCTION MISMATCH — HUMAN REVIEW REQUIRED</h2><p id="mismatch-alert-text">A durable transition requires human review.</p><div class="actions"><button id="enable-audible-alerts" class="button">Enable sound</button><button id="mute-audible-alerts" class="button secondary">Mute</button><button id="acknowledge-alert-locally" class="button secondary">Acknowledge locally</button></div></section><p id="watch-alert-live" class="skip" role="alert" aria-live="assertive"></p><section class="metrics"><article class="metric"><strong id="watch-stage">{{ watch.stage_label }}</strong><span>latest durable stage</span></article><article class="metric"><strong>{{ watch.source_label }}</strong><span>configured source</span></article><article class="metric"><strong>GET only</strong><span>browser authority</span></article></section><section class="section"><div class="section-head"><div><p class="eyebrow">Evidence pipeline</p><h2>Current bounded workflow</h2></div></div><div id="watch-pipeline" class="pipeline">{% for stage,label in [('DETECTED','Source'),('DIFF_READY','Diff'),('CANDIDATE_READY','Braille'),('IMPACT_READY','Impact'),('SEMANTIC_READY','Gemini'),('REPORT_READY','Report')] %}<article class="pipeline-step waiting" data-stage="{{ stage }}"><strong>{{ loop.index }} · {{ label }}</strong></article>{% endfor %}</div></section><section class="section"><div class="section-head"><div><p class="eyebrow">Safe next action</p><h2 id="watch-next-action">{{ watch.next_safe_action }}</h2></div></div><article id="watch-hero" class="report-hero" {% if not watch.hero %}hidden{% endif %}><p id="watch-hero-kicker" class="eyebrow">Professional report ready</p><h2 id="watch-hero-title"></h2><p id="watch-hero-status"></p><p id="watch-hero-impact"></p><a id="watch-hero-link" class="button" href="/">Review incident</a></article></section><section class="section"><div class="section-head"><div><p class="eyebrow">Persistent reports</p><h2>Review queue</h2></div></div><div class="card"><ul id="watch-incidents" class="watch-list">{% for incident in watch.incidents %}<li class="watch-incident"><a href="/incidents/{{ incident.incident_id }}">Report {{ incident.incident_id[:12] }}…</a><span class="meta">{{ incident.workflow_label }} · {{ incident.next_safe_action }}</span></li>{% endfor %}</ul><p id="watch-empty" {% if watch.incidents %}hidden{% endif %}>No report is currently awaiting review.</p></div></section>{% endblock %}"""

BASELINE = r"""{% extends 'base.html' %}{% block title %}Astra · Baseline{% endblock %}{% block content %}<div class="crumbs"><a href="/">Home</a><span>›</span><a href="/#baselines">Baselines</a><span>›</span><strong>{{ baseline.production_id|default('Unavailable') }}</strong></div><section class="hero"><div><p class="eyebrow">Registered baseline</p><h1>{{ baseline.production_id|default('Baseline unavailable') }}</h1><p class="lede"><strong>Registration successful.</strong> Immutable source-to-Braille lineage is ready to detect later drift. Registration generated evidence but performed no production action. No CUPS/device action was performed.</p></div><aside class="live-card"><span class="pill ok">{{ baseline.status|default('UNAVAILABLE')|replace('_',' ') }}</span><p><strong>State version</strong> {{ baseline.state_version|default('—') }}</p><p class="meta">{{ baseline.site_id|default('—') }} · {{ baseline.queue_name|default('—') }}</p></aside></section>{% if error %}<p class="notice">{{ error }}</p>{% else %}<section class="grid"><article class="card"><p class="eyebrow">Identity</p><h2>Baseline record</h2><p><strong>Baseline ID</strong><br><code>{{ baseline.baseline_id }}</code></p><p><strong>Registered</strong><br>{{ baseline.created_at }}</p></article><article class="card"><p class="eyebrow">Deterministic artifact</p><h2>Approved demo BRF</h2><p><strong>SHA-256</strong><br><code>{{ baseline.approved_brf_sha256 }}</code></p><span class="pill sim">Not a certified production master</span></article><article class="card"><p class="eyebrow">Authority</p><h2>What Astra did not do</h2><p>No CUPS submission, device control, endpoint completion, or physical output is claimed by registration.</p></article></section>{% endif %}<div class="actions"><a class="button teal" href="/watch">Monitor source</a><a class="button secondary" href="/">Back to dashboard</a></div>{% endblock %}"""

TEST = r"""{% extends 'base.html' %}{% block title %}Astra · Explore{% endblock %}{% block content %}<div class="crumbs"><a href="/">Home</a><span>›</span><strong>Explore Astra</strong></div><section class="hero"><div><p class="eyebrow">Project guide</p><h1>Two paths. Same evidence boundaries.</h1><p class="lede">Explore the deployed read-only evidence dashboard in minutes, or reproduce the full Google Cloud and simulated production-floor workflow in a separate account.</p></div></section><section class="grid"><article class="card"><span class="pill ok">Path A · hosted view</span><h2>Explore the deployed dashboard</h2><ol><li>Open the live watch floor.</li><li>Inspect a registered baseline.</li><li>Open a past report and its human outcome.</li><li>Compare source, Braille impact, Gemini assessment, and audit timeline.</li></ol><div class="actions"><a class="button teal" href="/watch">Open live watch</a>{% if source_document_url %}<a class="button secondary" href="{{ source_document_url }}" target="_blank" rel="noopener">View source document</a>{% endif %}</div><p class="meta">This public path is GET-only. It cannot submit decisions, edit Drive, or control CUPS/devices.</p></article><article class="card"><span class="pill">Path B · full reproduction</span><h2>Run Astra in a separate account</h2><ol><li>Clone the repository.</li><li>Follow the fresh-project deployment guide.</li><li>Share one source read-only with the runtime identity.</li><li>Run Liblouis and the CUPS simulator locally.</li><li>Enable the private automation cycle and make a source correction.</li></ol><div class="actions"><a class="button" href="{{ repository_url }}" target="_blank" rel="noopener">Open GitHub repository</a></div><p class="meta">This path demonstrates portability while keeping cloud identity under the account that runs it.</p></article></section><section class="section"><div class="outcome"><p class="eyebrow">Important boundary</p><h2>Only the physical embosser is simulated.</h2><p>Drive refetch, deterministic Liblouis BRF generation, page impact, Gemini assessment, durable state, and CUPS queue/capture behavior are real. Human authority stays human.</p></div></section>{% endblock %}"""

MODERN_TEMPLATES = {
    "base.html": BASE,
    "index.html": INDEX,
    "watch.html": WATCH,
    "baseline_monitor.html": BASELINE,
    "test_astra.html": TEST,
}
